package il.co.aniparve.widget
import android.app.*
import android.appwidget.*
import android.content.*
import android.os.*
import android.widget.RemoteViews
import il.co.aniparve.*
import android.text.format.DateFormat
import java.util.Date
import java.util.concurrent.TimeUnit
class TimerWidgetProvider:AppWidgetProvider(){
 override fun onUpdate(c:Context,m:AppWidgetManager,ids:IntArray)=WidgetUpdater.updateAll(c)
 override fun onAppWidgetOptionsChanged(c:Context,m:AppWidgetManager,id:Int,o:Bundle)=WidgetUpdater.updateAll(c)
 override fun onReceive(c:Context,i:Intent){super.onReceive(c,i);if(i.action==TICK)WidgetUpdater.updateAll(c)}
 companion object{const val TICK="il.co.aniparve.widget.TICK"}
}
object WidgetUpdater{
 fun updateAll(c:Context){val m=AppWidgetManager.getInstance(c);val ids=m.getAppWidgetIds(ComponentName(c,TimerWidgetProvider::class.java));if(ids.isEmpty())return;val active=TimerStore.all(c).filter{it.status=="active"}.sortedBy{it.endAt};ids.forEach{id->val v=RemoteViews(c.packageName,R.layout.timer_widget);if(active.isEmpty()){v.setViewVisibility(R.id.widget_empty,android.view.View.VISIBLE);v.setViewVisibility(R.id.widget_active,android.view.View.GONE);v.setOnClickPendingIntent(R.id.widget_open,pi(c,1,null,false));v.setOnClickPendingIntent(R.id.widget_empty,pi(c,1,null,false));v.setOnClickPendingIntent(R.id.widget_meat,pi(c,2,"meat",false));v.setOnClickPendingIntent(R.id.widget_dairy,pi(c,3,"dairy",false))}else{val t=active[0];v.setViewVisibility(R.id.widget_empty,android.view.View.GONE);v.setViewVisibility(R.id.widget_active,android.view.View.VISIBLE);v.setTextViewText(R.id.widget_name,if(t.name=="אני")"אני פרווה בעוד" else t.name+" פרווה בעוד");val now=Date();val target=Date(t.endAt);val df=java.text.SimpleDateFormat("yyyyMMdd",java.util.Locale.getDefault());val prefix=when{df.format(now)==df.format(target)->"";df.format(Date(now.time+86400000L))==df.format(target)->"מחר ";else->"ביום "+java.text.SimpleDateFormat("EEEE",java.util.Locale.getDefault()).format(target)+" "};v.setTextViewText(R.id.widget_end,"פרווה "+prefix+"בשעה "+DateFormat.getTimeFormat(c).format(target));v.setTextViewText(R.id.widget_more,if(active.size>1)"+"+(active.size-1)+" טיימרים נוספים" else "");val left=(t.endAt-System.currentTimeMillis()).coerceAtLeast(0);if(Build.VERSION.SDK_INT>=24){v.setViewVisibility(R.id.widget_chrono,android.view.View.VISIBLE);v.setViewVisibility(R.id.widget_remaining,android.view.View.GONE);v.setChronometer(R.id.widget_chrono,SystemClock.elapsedRealtime()+left,null,true);v.setChronometerCountDown(R.id.widget_chrono,true)}else{v.setViewVisibility(R.id.widget_chrono,android.view.View.GONE);v.setViewVisibility(R.id.widget_remaining,android.view.View.VISIBLE);val mins=TimeUnit.MILLISECONDS.toMinutes(left+59999);v.setTextViewText(R.id.widget_remaining,(mins/60).toString()+" שעות ו־"+(mins%60)+" דקות");minuteTick(c)};v.setOnClickPendingIntent(R.id.widget_active,pi(c,4,null,true))};m.updateAppWidget(id,v)};if(active.isEmpty())cancelTick(c)}
 private fun pi(c:Context,req:Int,type:String?,timers:Boolean):PendingIntent{val i=Intent(c,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP);if(type!=null)i.putExtra("start_type",type).putExtra("open_start_sheet",true);if(timers)i.putExtra("show_timers",true);val f=PendingIntent.FLAG_UPDATE_CURRENT or if(Build.VERSION.SDK_INT>=23)PendingIntent.FLAG_IMMUTABLE else 0;return PendingIntent.getActivity(c,req,i,f)}
 private fun minuteTick(c:Context){val am=c.getSystemService(Context.ALARM_SERVICE) as AlarmManager;val f=PendingIntent.FLAG_UPDATE_CURRENT or if(Build.VERSION.SDK_INT>=23)PendingIntent.FLAG_IMMUTABLE else 0;val pi=PendingIntent.getBroadcast(c,7001,Intent(c,TimerWidgetProvider::class.java).setAction(TimerWidgetProvider.TICK),f);try{if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+60000,pi)else am.setExact(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+60000,pi)}catch(_:SecurityException){am.set(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+60000,pi)}}
 private fun cancelTick(c:Context){val am=c.getSystemService(Context.ALARM_SERVICE) as AlarmManager;val f=PendingIntent.FLAG_UPDATE_CURRENT or if(Build.VERSION.SDK_INT>=23)PendingIntent.FLAG_IMMUTABLE else 0;am.cancel(PendingIntent.getBroadcast(c,7001,Intent(c,TimerWidgetProvider::class.java).setAction(TimerWidgetProvider.TICK),f))}
}